//! One-way logical bridge: independent domains and authenticated sealed artifacts.
use crate::*;
use ed25519_dalek::{Signer,SigningKey,VerifyingKey,Signature};
use chacha20poly1305::{XChaCha20Poly1305,KeyInit,aead::{Aead,Payload}};
use sha2::{Sha256,Digest};
use x25519_dalek::{StaticSecret,PublicKey};
use std::{path::{Path,PathBuf},fs,io::{Read,Write,Seek}};
const FILE_MAGIC:&[u8]=b"MURMUR-BRIDGE-FILE-1\0";
fn file_payload(part:&FilePart)->Result<Vec<u8>>{let mut out=FILE_MAGIC.to_vec();out.extend(encode(part)?);Ok(out)}
#[derive(Clone,Copy,Debug,PartialEq,Eq,Serialize,Deserialize)]
pub enum Role {LowExporter,HighReceiver}
#[derive(Clone)]
pub struct Config {pub domain:NodeId,pub trusted_domains:BTreeSet<NodeId>,pub trusted_origins:BTreeMap<NodeId,[u8;32]>,pub role:Role,pub directory:PathBuf,pub stream:String,pub recipient:[u8;32],pub receiver_secret:Option<zeroize::Zeroizing<[u8;32]>>,pub signer:Option<zeroize::Zeroizing<[u8;32]>>,pub trusted_signers:BTreeMap<NodeId,[u8;32]>,pub max_bundle_bytes:usize,pub max_payload_bytes:usize,pub staging_bytes:usize}
impl std::fmt::Debug for Config {fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{f.debug_struct("Bridge").field("role",&self.role).field("stream",&self.stream).finish_non_exhaustive()}}
impl Config {pub fn validate(&self)->Result<()>{if self.domain==[0;16] || self.role==Role::HighReceiver && self.trusted_domains.is_empty() || self.stream.is_empty() || self.stream.len()>64 || !self.stream.bytes().all(|b|b.is_ascii_alphanumeric() || b"-_".contains(&b)) || self.max_bundle_bytes==0 || self.max_bundle_bytes>16<<20 || self.max_payload_bytes==0 || self.max_payload_bytes>64<<20 || self.staging_bytes<self.max_bundle_bytes || self.role==Role::LowExporter && self.signer.is_none() || self.role==Role::HighReceiver && self.receiver_secret.is_none(){return Err(Error::Invalid("bridge configuration".into()));}Ok(())}}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct Origin {pub node:NodeId,pub sequence:u64,pub transaction:NodeId,pub digest:[u8;32]}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct Header {pub origin:Option<Origin>,pub source_database:NodeId,pub source_node:NodeId,pub stream:String,pub sequence:u64,pub bundle:NodeId,pub recipient:[u8;32],pub ephemeral:[u8;32],pub nonce:[u8;24],pub digest:[u8;32]}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct Bundle {pub version:u16,pub header:Header,pub ciphertext:Vec<u8>,pub signature:Vec<u8>}
pub struct Bridge {config:Config,backend:Arc<dyn Backend>,gate:std::sync::Mutex<()>,files:std::sync::Mutex<Option<Arc<crate::files::Objects>>>}
#[derive(Clone,Serialize,Deserialize)]
struct FilePart {name:String,digest:[u8;32],bytes:u64,offset:u64,data:Vec<u8>,final_part:bool}
impl Bridge {
    pub fn open(config:Config,backend:Arc<dyn Backend>)->Result<Self>{config.validate()?;if config.domain!=backend.identity().0{return Err(Error::Invalid("bridge domain mismatch".into()));}fs::create_dir_all(&config.directory)?;Ok(Self{config,backend,gate:std::sync::Mutex::new(()),files:std::sync::Mutex::new(None)})}
    pub fn attach_files(&self,files:Option<Arc<crate::files::Objects>>){*self.files.lock().unwrap()=files;}
    pub fn export(&self,payload:&[u8])->Result<PathBuf>{self.export_origin(payload,None)}
    fn export_origin(&self,payload:&[u8],origin:Option<Origin>)->Result<PathBuf>{if self.config.role!=Role::LowExporter{return Err(Error::Invalid("bridge direction".into()));}if payload.len()>self.config.max_payload_bytes{return Err(Error::Overloaded);}let(db,node)=self.backend.identity();let sequence_key=format!("09/bridge/export/{}/sequence",self.config.stream).into_bytes();let sequence=self.backend.get(&sequence_key)?.map(|b|decode::<u64>(&b)).transpose()?.unwrap_or(0).checked_add(1).ok_or(Error::Overloaded)?;let ephemeral=StaticSecret::from(rand::random::<[u8;32]>());let secret=ephemeral.diffie_hellman(&PublicKey::from(self.config.recipient));if secret.as_bytes()==&[0;32]{return Err(Error::Auth("invalid bridge recipient".into()));}let header=Header{origin,source_database:db,source_node:node,stream:self.config.stream.clone(),sequence,bundle:rand::random(),recipient:self.config.recipient,ephemeral:PublicKey::from(&ephemeral).to_bytes(),nonce:rand::random(),digest:Sha256::digest(payload).into()};let aad=encode(&header)?;let key=derive(secret.as_bytes(),&aad)?;let compressed=zstd::stream::encode_all(payload,3)?;let cipher=XChaCha20Poly1305::new_from_slice(&*key).unwrap();let ciphertext=cipher.encrypt((&header.nonce).into(),Payload{msg:&compressed,aad:&aad}).map_err(|_|Error::Auth("bridge encryption".into()))?;let mut bundle=Bundle{version:1,header,ciphertext,signature:Vec::new()};bundle.signature=SigningKey::from_bytes(self.config.signer.as_deref().unwrap()).sign(&signed(&bundle)?).to_bytes().to_vec();let bytes=encode(&bundle)?;if bytes.len()>self.config.max_bundle_bytes{return Err(Error::Overloaded);}let path=self.config.directory.join(format!("{}-{sequence:020}.bundle",hex(&node)));let pending=self.config.directory.join(format!(".{}.pending",hex(&bundle.header.bundle)));let mut file=crate::files::private_file(&pending)?;file.write_all(&bytes)?;file.sync_all()?;self.backend.commit(vec![Record::put(format!("09/bridge/outbox/{}",hex(&bundle.header.bundle)).into_bytes(),bytes),Record::put(sequence_key,encode(&sequence)?)])?;fs::rename(pending,&path)?;fs::File::open(&self.config.directory)?.sync_all()?;Ok(path)}
    pub fn open_bundle(&self,bytes:&[u8])->Result<(Header,Vec<u8>)>{if self.config.role!=Role::HighReceiver || bytes.len()>self.config.max_bundle_bytes{return Err(Error::Invalid("bridge role or artifact size".into()));}let bundle:Bundle=decode(bytes)?;if bundle.version!=1 || !self.config.trusted_domains.contains(&bundle.header.source_database) || bundle.header.sequence==0 || bundle.header.stream!=self.config.stream{return Err(Error::Protocol("bridge envelope".into()));}let public=self.config.trusted_signers.get(&bundle.header.source_node).ok_or_else(||Error::Auth("untrusted bridge signer".into()))?;VerifyingKey::from_bytes(public).map_err(|e|Error::Auth(e.to_string()))?.verify_strict(&signed(&bundle)?,&Signature::from_slice(&bundle.signature).map_err(|e|Error::Auth(e.to_string()))?).map_err(|e|Error::Auth(e.to_string()))?;let secret=StaticSecret::from(*self.config.receiver_secret.as_deref().unwrap());if PublicKey::from(&secret).to_bytes()!=bundle.header.recipient{return Err(Error::Auth("bridge recipient mismatch".into()));}let shared=secret.diffie_hellman(&PublicKey::from(bundle.header.ephemeral));if shared.as_bytes()==&[0;32]{return Err(Error::Auth("invalid bridge sender key".into()));}let aad=encode(&bundle.header)?;let key=derive(shared.as_bytes(),&aad)?;let compressed=XChaCha20Poly1305::new_from_slice(&*key).unwrap().decrypt((&bundle.header.nonce).into(),Payload{msg:&bundle.ciphertext,aad:&aad}).map_err(|_|Error::Auth("bridge authentication".into()))?;let decoder=zstd::stream::read::Decoder::new(compressed.as_slice())?;let mut payload=Vec::new();decoder.take(self.config.max_payload_bytes as u64+1).read_to_end(&mut payload)?;if payload.len()>self.config.max_payload_bytes || <[u8;32]>::from(Sha256::digest(&payload))!=bundle.header.digest{return Err(Error::Auth("bridge payload digest or size".into()));}Ok((bundle.header,payload))}
    /// Authenticate before staging; preserve gaps and identity conflicts across restart.
    pub fn stage(&self,path:&Path)->Result<Header>{if fs::metadata(path)?.len()>self.config.max_bundle_bytes as u64{return Err(Error::Overloaded);}let bytes=fs::read(path)?;let(header,_)=self.open_bundle(&bytes)?;let key=format!("09/bridge/inbox/{}/{}/{:020}",hex(&header.source_database),header.stream,header.sequence).into_bytes();if let Some(old)=self.backend.get(&key)?{let(previous,_)=self.open_bundle(&old)?;if previous.bundle!=header.bundle || previous.digest!=header.digest{return Err(Error::Auth("conflicting bridge sequence".into()));}}else{let keys=self.backend.keys(b"09/bridge/inbox/")?;let mut total=bytes.len();for k in keys {total+=self.backend.get(&k)?.map_or(0,|b|b.len());if total>self.config.staging_bytes{return Err(Error::Overloaded);}}self.backend.commit(vec![Record::put(key,bytes)])?;}Ok(header)}
    pub fn release(&self,table:impl Into<String>,key:Vec<u8>,column:Option<String>)->Result<bool>{if self.config.role!=Role::HighReceiver{return Err(Error::Invalid("bridge direction".into()));}self.backend.release_ownership(table.into(),key,column)}
    pub fn export_snapshot(&self)->Result<PathBuf>{self.export(&self.backend.snapshot()?)}
    /// Export one named file as bounded sealed bridge bundles. The current
    /// offset is durable in Spool and resumes safely after a restart.
    pub fn export_file(&self,name:&str)->Result<()>{let _gate=self.gate.lock().unwrap();self.export_file_locked(name)}
    fn export_file_locked(&self,name:&str)->Result<()>{let objects=self.files.lock().unwrap().clone().ok_or_else(||Error::Invalid("bridge file storage is not configured".into()))?;let meta=objects.metadata(name)?.filter(|m|!m.deleted).ok_or_else(||Error::Unavailable("file metadata missing".into()))?;let progress_key=format!("09/bridge/file-export/{}/{}",self.config.stream,hex(&Sha256::digest(name.as_bytes()))).into_bytes();let saved=self.backend.get(&progress_key)?.map(|b|decode::<([u8;32],u64,u64,bool)>(&b)).transpose()?;if saved.is_some_and(|(d,g,_,done)|d==meta.digest&&g==meta.generation&&done){return Ok(());}let skip=saved.filter(|(digest,generation,_,_)|*digest==meta.digest&&*generation==meta.generation).map(|v|v.2).unwrap_or(0);let mut offset=skip;let max_chunk=self.config.max_payload_bytes.saturating_sub(name.len()+256).min(64<<10);if max_chunk==0{return Err(Error::Overloaded);}let (current,total)=objects.stream_plain_chunks(name,skip,max_chunk,|at,data|{let part=FilePart{name:name.into(),digest:meta.digest,bytes:meta.bytes,offset:at,data:data.to_vec(),final_part:false};self.export_origin(&file_payload(&part)?,None)?;offset=at+data.len() as u64;self.backend.commit(vec![Record::put(progress_key.clone(),encode(&(meta.digest,meta.generation,offset,false))?)])?;Ok(())})?;if current.digest!=meta.digest||current.generation!=meta.generation{return Err(Error::Unavailable("file changed during bridge export".into()));}if total!=meta.bytes{return Err(Error::Auth("bridge file length".into()));}let final_part=FilePart{name:name.into(),digest:meta.digest,bytes:meta.bytes,offset:total,data:Vec::new(),final_part:true};self.export_origin(&file_payload(&final_part)?,None)?;self.backend.commit(vec![Record::put(progress_key,encode(&(meta.digest,meta.generation,total,true))?)])?;Ok(())}
    fn capture_file_locked(&self)->Result<bool>{let Some(objects)=self.files.lock().unwrap().clone() else{return Ok(false)};for meta in objects.list()?{if !objects.available(&meta.name)?{continue;}let key=format!("09/bridge/file-export/{}/{}",self.config.stream,hex(&Sha256::digest(meta.name.as_bytes()))).into_bytes();let done=self.backend.get(&key)?.map(|b|decode::<([u8;32],u64,u64,bool)>(&b)).transpose()?.is_some_and(|(d,g,_,done)|d==meta.digest&&g==meta.generation&&done);if !done{self.export_file_locked(&meta.name)?;return Ok(true);}}Ok(false)}
    /// Automatic capture reads immutable signed transactions, including forwarded origins.
    pub fn capture(&self)->Result<usize>{if self.config.role!=Role::LowExporter{return Ok(0);}let _gate=self.gate.lock().unwrap();let mut count=0;
        for key in self.backend.keys(b"07/replication/log/")? {if count>=4 {break;}let Some(bytes)=self.backend.get(&key)? else {continue;};let tx:crate::protocol::Transaction=decode(&bytes)?;
            let progress_key=format!("09/bridge/exported/{}/{}",self.config.stream,hex(&tx.origin)).into_bytes();let previous=self.backend.get(&progress_key)?.map(|b|decode::<u64>(&b)).transpose()?.unwrap_or(0);if tx.sequence<=previous {continue;}
            self.export_origin(&bytes,Some(Origin{node:tx.origin,sequence:tx.sequence,transaction:tx.id,digest:tx.digest()?}))?;
            self.backend.commit(vec![Record::put(progress_key,encode(&tx.sequence)?)])?;count+=1;
        }if count<4&&self.capture_file_locked()?{count+=1;}Ok(count)
    }
    pub fn process(&self)->Result<usize>{if self.config.role!=Role::HighReceiver{return Ok(0);}let _gate=self.gate.lock().unwrap();let mut artifacts:Vec<_>=fs::read_dir(&self.config.directory)?.filter_map(|e|e.ok().map(|e|e.path())).filter(|p|p.extension().is_some_and(|e|e=="bundle")).collect();artifacts.sort();
        for path in artifacts.into_iter().take(256) {if let Err(error)=self.stage(&path){let bytes=fs::read(&path)?;let key=format!("09/bridge/quarantine/{}",hex(&Sha256::digest(&bytes))).into_bytes();self.backend.commit(vec![Record::put(key,encode(&(error.to_string(),bytes))?)])?;let quarantine=self.config.directory.join("quarantine");fs::create_dir_all(&quarantine)?;if let Some(name)=path.file_name(){fs::rename(&path,quarantine.join(name))?;}}}
        let mut count=0;for key in self.backend.keys(b"09/bridge/inbox/")? {if count>=4{break;}let Some(bytes)=self.backend.get(&key)? else {continue;};let(header,mut payload)=self.open_bundle(&bytes)?;
            let progress_key=format!("09/bridge/applied/{}/{}",hex(&header.source_database),header.stream).into_bytes();let applied=self.backend.get(&progress_key)?.map(|b|decode::<u64>(&b)).transpose()?.unwrap_or(0);
            if header.sequence<=applied {continue;}if header.sequence!=applied+1 {continue;}
            if let Some(origin)=&header.origin {let tx:crate::protocol::Transaction=decode(&payload)?;tx.verify(header.source_database,&self.config.trusted_origins,self.config.max_payload_bytes)?;if tx.origin!=origin.node || tx.sequence!=origin.sequence || tx.id!=origin.transaction || tx.digest()?!=origin.digest{return Err(Error::Auth("bridge origin proof mismatch".into()));}payload=tx.payload;}
            if payload.starts_with(FILE_MAGIC){match self.process_file_part(&header,&payload){Ok(cleanup)=>{self.backend.commit(vec![Record::put(progress_key,encode(&header.sequence)?)])?;if let Some(path)=cleanup{let _=fs::remove_file(path);}count+=1;},Err(error)=>{self.backend.commit(vec![Record::put(format!("09/bridge/hold/{}",hex(&header.bundle)).into_bytes(),encode(&error.to_string())?)])?;}}}else{match self.backend.import_bridge(header.clone(),payload) {Ok(true)=>{self.backend.commit(vec![Record::put(progress_key,encode(&header.sequence)?)])?;count+=1;},Ok(false)=>{},Err(error)=>{self.backend.commit(vec![Record::put(format!("09/bridge/hold/{}",hex(&header.bundle)).into_bytes(),encode(&error.to_string())?)])?;}}}
        }Ok(count)
    }
    fn process_file_part(&self,header:&Header,payload:&[u8])->Result<Option<PathBuf>>{let objects=self.files.lock().unwrap().clone().ok_or_else(||Error::Invalid("bridge file storage is not configured".into()))?;let part:FilePart=decode(&payload[FILE_MAGIC.len()..])?;if part.name.is_empty()||part.name.len()>4096||part.name.contains('\0')||part.bytes>self.config.staging_bytes as u64||part.offset>part.bytes||part.offset.checked_add(part.data.len() as u64).is_none_or(|end|end>part.bytes)||part.final_part&&(part.offset!=part.bytes||!part.data.is_empty()){return Err(Error::Protocol("bridge file chunk bounds".into()));}let transfer=hex(&Sha256::digest(encode(&(header.source_database,&header.stream,&part.name,part.digest))?));let path=self.config.directory.join(format!(".file-{transfer}.part"));let received_key=format!("09/bridge/file-received/{transfer}").into_bytes();if part.final_part&&!path.exists()&&self.backend.get(&received_key)?.is_some(){return Ok(None);}if !path.exists(){let _=crate::files::private_file(&path)?;}let mut file=fs::OpenOptions::new().read(true).write(true).open(&path)?;let length=file.metadata()?.len();let mut staged=0u64;for entry in fs::read_dir(&self.config.directory)?{let entry=entry?;if entry.file_name().to_string_lossy().starts_with(".file-"){staged=staged.saturating_add(entry.metadata()?.len());}}let additional=if length==part.offset{part.data.len() as u64}else{0};if staged.saturating_add(additional)>self.config.staging_bytes as u64{return Err(Error::Overloaded);}if length==part.offset{file.seek(std::io::SeekFrom::Start(part.offset))?;file.write_all(&part.data)?;file.sync_all()?;}else if length>=part.offset+part.data.len() as u64{file.seek(std::io::SeekFrom::Start(part.offset))?;let mut old=vec![0;part.data.len()];file.read_exact(&mut old)?;if old!=part.data{return Err(Error::Auth("conflicting bridge file chunk".into()));}}else{return Err(Error::Protocol("bridge file chunk offset".into()));}if !part.final_part{return Ok(None);}if file.metadata()?.len()!=part.bytes{return Err(Error::Unavailable("incomplete bridge file".into()));}file.seek(std::io::SeekFrom::Start(0))?;let mut hash=Sha256::new();let mut buffer=[0;64<<10];loop{let n=file.read(&mut buffer)?;if n==0{break;}hash.update(&buffer[..n]);}if <[u8;32]>::from(hash.finalize())!=part.digest{return Err(Error::Auth("bridge file digest".into()));}drop(file);let uploaded=objects.upload(&part.name,fs::File::open(&path)?)?;if uploaded.digest!=part.digest||uploaded.bytes!=part.bytes{return Err(Error::Auth("bridge file content mismatch".into()));}self.backend.commit(vec![Record::put(received_key,encode(&(part.digest,part.bytes))?)])?;Ok(Some(path))}
    pub async fn publish_http(&self,path:&Path,url:&str)->Result<()>{if self.config.role!=Role::LowExporter || !(url.starts_with("https://") || url.starts_with("http://")){return Err(Error::Invalid("bridge export URL".into()));}let data=fs::read(path)?;if data.len()>self.config.max_bundle_bytes{return Err(Error::Overloaded);}reqwest::Client::new().put(url).body(data).send().await.map_err(|e|Error::Unavailable(e.to_string()))?.error_for_status().map_err(|e|Error::Unavailable(e.to_string()))?;Ok(())}
}
fn signed(bundle:&Bundle)->Result<Vec<u8>>{let mut bytes=b"murmur/sqlite-bridge/v1".to_vec();bytes.extend(encode(&(bundle.version,&bundle.header,Sha256::digest(&bundle.ciphertext).to_vec()))?);Ok(bytes)}
fn derive(secret:&[u8;32],aad:&[u8])->Result<zeroize::Zeroizing<[u8;32]>>{let hk=hkdf::Hkdf::<Sha256>::new(Some(b"murmur/sqlite-bridge/v1"),secret);let mut key=zeroize::Zeroizing::new([0;32]);hk.expand(aad,&mut *key).map_err(|_|Error::Auth("bridge key derivation".into()))?;Ok(key)}

impl Config {
    pub fn exporter(domain:NodeId,directory:PathBuf,stream:String,signer:[u8;32],recipient:[u8;32])->Self {Self{domain,trusted_domains:BTreeSet::new(),trusted_origins:BTreeMap::new(),role:Role::LowExporter,directory,stream,recipient,receiver_secret:None,signer:Some(zeroize::Zeroizing::new(signer)),trusted_signers:BTreeMap::new(),max_bundle_bytes:16<<20,max_payload_bytes:64<<20,staging_bytes:1<<30}}
    pub fn receiver(domain:NodeId,directory:PathBuf,stream:String,secret:[u8;32],trusted_domains:BTreeSet<NodeId>,trusted_signers:BTreeMap<NodeId,[u8;32]>,trusted_origins:BTreeMap<NodeId,[u8;32]>)->Self {Self{domain,trusted_domains,trusted_origins,role:Role::HighReceiver,directory,stream,recipient:PublicKey::from(&StaticSecret::from(secret)).to_bytes(),receiver_secret:Some(zeroize::Zeroizing::new(secret)),signer:None,trusted_signers,max_bundle_bytes:16<<20,max_payload_bytes:64<<20,staging_bytes:1<<30}}
}
pub fn recipient_public(secret:[u8;32])->[u8;32] {PublicKey::from(&StaticSecret::from(secret)).to_bytes()}
